import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), gameEl=$('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x07110f);scene.fog=new THREE.FogExp2(0x07110f,.027);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,100);camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;gameEl.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0x9abdb1,0x151d1b,1.12));const key=new THREE.DirectionalLight(0xb7d8c6,1.25);key.position.set(-5,12,4);scene.add(key);
const mat=(color,roughness=.82,metalness=0,emissive=0x000000)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:1});
const M={floor:mat(0x263230),wall:mat(0x384442),dark:mat(0x141d1b),trim:mat(0x75847d,.55,.3),crate:mat(0x5b6254),crate2:mat(0x424c45),yellow:mat(0xb2a14c),cyan:mat(0x7affdc,.38,.1,0x17a97d),red:mat(0xff563c,.5,.1,0xb51b12),white:mat(0xc8d4ca),black:mat(0x101514,.5,.55),gun:mat(0x222b29,.32,.6),screen:mat(0x4effbb,.28,.05,0x18a76b)};
function box(x,y,z,w,h,d,m,opts={}){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=false;o.receiveShadow=true;if(opts.rot)o.rotation.y=opts.rot;scene.add(o);return o}
function cylinder(x,y,z,r1,r2,h,m,seg=10){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),m);o.position.set(x,y,z);scene.add(o);return o}
function pointLight(x,y,z,color,intensity,distance){const l=new THREE.PointLight(color,intensity,distance,2);l.position.set(x,y,z);scene.add(l);return l}
const worldBounds={minX:-15.5,maxX:15.5,minZ:-39,maxZ:12};
function buildWorld(){
 box(0,-.28,-13,34,.5,54,M.floor);
 // subtle floor panels / luminous hazard guides
 for(let z=9;z>-39;z-=4){box(0,-.015,z,31,.025,.035,M.dark);}
 for(let x=-15;x<=15;x+=5)box(x,-.01,-13,.025,.02,51,M.trim);
 // outer shell
 box(0,2.1,13,34,4.2,.7,M.wall);box(0,2.1,-40,34,4.2,.7,M.wall);
 box(-16.8,2.1,-13,.7,4.2,54,M.wall);box(16.8,2.1,-13,.7,4.2,54,M.wall);
 // ceiling beams
 for(let z=10;z>-39;z-=6){box(0,4.3,z,33,.22,.28,M.dark);for(let x of [-10,0,10])box(x,4.14,z,.045,.04,2,M.trim);}
 // central transit hall to operations wing; side partition segments and door gaps
 box(-5.4,1.8,-7, .45,3.6,26,M.wall);box(5.4,1.8,-7,.45,3.6,26,M.wall);
 // west rooms division with service door gap
 box(-10.4,1.8,-9,10.5,3.6,.38,M.wall);box(-10.4,1.8,-21,10.5,3.6,.38,M.wall);
 // east operations wing, entry gap in south partition
 box(10.7,1.8,-22,12,3.6,.4,M.wall);box(10.7,1.8,-32,12,3.6,.4,M.wall);
 box(13.7,1.8,-27, .4,3.6,10,M.wall);
 // doors: frames and open negative spaces; steel uprights identify passage
 for(const [x,z] of [[-5.3,-9],[5.3,-22]]){box(x,1.8,z,.18,3.6,.3,M.trim);box(x,3.55,z,2.2,.16,.3,M.trim);}
 // structural columns / equipment racks
 for(const [x,z] of [[-9,7],[9,7],[-9,-3],[9,-4],[-12,-14],[12,-16],[-11,-29],[10,-36]]){
   box(x,1.65,z,.85,3.3,.85,M.dark);box(x,.5,z,.98,.18,.98,M.trim);box(x,3.15,z,.98,.16,.98,M.trim);
   box(x,2.7,z+.44,.22,.32,.04,M.cyan);
 }
 // stacked storage crates
 const crate=(x,z,w=1.4,d=1.2,h=1.25,m=M.crate)=>{box(x,h/2,z,w,h,d,m);box(x,h+.025,z,w+.04,.08,d+.04,M.trim);box(x,h/2,z-d/2-.012,w*.8,.08,.025,M.dark);for(let dx of [-w*.38,w*.38])box(x+dx,h/2,z,.06,h*.88,.04,M.trim);};
 crate(-12,5,2,1.5,1.4);crate(-12,2,1.3,1.3,1.2,M.crate2);crate(12,1,1.9,1.4,1.5);crate(11,-7,1.5,1.4,1.2);
 crate(-12,-27,2,1.4,1.5);crate(12,-36,1.6,1.6,1.4);crate(-2,-30,1.6,1.5,1.35);
 // wall consoles in intel room
 for(let x=6;x<12;x+=1.55){box(x,1.1,-37.4,1.25,1.9,.45,M.dark);box(x,1.72,-37.14,1.08,.54,.07,M.screen);box(x,2.15,-37.35,1.25,.06,.5,M.trim);}
 // operating desk / elevated core plinth
 box(8.7,.58,-26.4,4.8,1.05,1.5,M.dark);box(8.7,1.13,-26.4,4.95,.12,1.62,M.trim);
 // extraction gate and status pylons
 for(const x of [-2.1,2.1]){box(x,2,-38.1,.22,4,.28,M.dark);box(x,2,-37.91,.1,3.55,.05,M.cyan);pointLight(x,2,-37.6,0x65ffd1,1.4,5);}
 box(0,4,-38.05,4.4,.22,.3,M.dark);box(0,4,-37.88,3.7,.09,.07,M.cyan);
 // ceiling lights with luminous fixtures and pools
 for(const [x,z] of [[0,8],[-1,-1],[0,-9],[-1,-18],[8,-23],[8,-33],[0,-35],[-9,-12]]){
   box(x,4.04,z,1.35,.06,.48,M.screen);pointLight(x,3.75,z,0x7bdfbd,3.3,11);
 }
 // warning beacons, pipes and readable industrial details
 for(let z=8;z>-39;z-=8){box(-15.9,3.4,z,.15,.1,1.1,M.yellow);box(15.9,3.4,z,.15,.1,1.1,M.red);}
 for(let z=8;z>-38;z-=3){cylinder(-15.95,3.62,z,.07,.07,2.7,M.trim,8);}
 // center corridor striping
 for(let z=8;z>-30;z-=2){box(-.45,.012,z,.07,.02,.65,M.yellow);box(.45,.012,z,.07,.02,.65,M.yellow);}
}
buildWorld();
const player={pos:new THREE.Vector3(0,0,9),yaw:0,pitch:0,health:100,ammo:12,reserve:48,mag:12,alive:true,speed:5.2};
camera.position.set(player.pos.x,1.68,player.pos.z);scene.add(camera);

