const gunBody=new THREE.Mesh(new THREE.BoxGeometry(.17,.18,.46),M.gun);gun.add(gunBody);gunBody.position.set(0,0,-.08);
const slide=new THREE.Mesh(new THREE.BoxGeometry(.145,.075,.34),M.trim);slide.position.set(0,.09,-.08);gun.add(slide);
const grip=new THREE.Mesh(new THREE.BoxGeometry(.12,.22,.14),M.black);grip.position.set(0,-.15,.06);grip.rotation.x=-.22;gun.add(grip);
const barrel=new THREE.Mesh(new THREE.CylinderGeometry(.038,.038,.27,10),M.black);barrel.rotation.x=Math.PI/2;barrel.position.set(0,.005,-.35);gun.add(barrel);
const muzzleFlash=new THREE.Mesh(new THREE.ConeGeometry(.12,.28,8),new THREE.MeshBasicMaterial({color:0xffdd85,transparent:true,opacity:.9}));muzzleFlash.rotation.x=-Math.PI/2;muzzleFlash.position.set(0,.005,-.58);muzzleFlash.visible=false;gun.add(muzzleFlash);
const enemies=[];
function makeEnemy(x,z,patrol=0){
 const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);g.userData={hp:100,alive:true,origin:new THREE.Vector3(x,0,z),patrol,phase:Math.random()*6,fire:1+Math.random()*1.8};
 const uniform=mat(0x263c39),vest=mat(0x182a28),skin=mat(0x927c69),visor=mat(0x15201e,.2,.3,0x220e08);
 const torso=new THREE.Mesh(new THREE.BoxGeometry(.55,.74,.34),uniform);torso.position.y=1.18;g.add(torso);
 const armor=new THREE.Mesh(new THREE.BoxGeometry(.58,.42,.37),vest);armor.position.set(0,1.25,-.015);g.add(armor);
