function onKey(e,down){const k=e.key.toLowerCase();if(down)keys.add(k);else keys.delete(k);if(['w','a','s','d',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(down&&k==='r')reload();if(down&&k===' '&&state.running)fire();}
addEventListener('keydown',e=>onKey(e,true));addEventListener('keyup',e=>onKey(e,false));
renderer.domElement.addEventListener('click',()=>{if(state.running&&innerWidth>700)renderer.domElement.requestPointerLock?.();if(state.running&&document.pointerLockElement===renderer.domElement)fire();});
addEventListener('mousemove',e=>{if(state.running&&document.pointerLockElement===renderer.domElement){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.28,Math.min(1.28,player.pitch-e.movementY*.002));}});
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
function bindStick(){const base=$('#joystick'),knob=$('#stick');let pid=null;const move=e=>{if(pid!==e.pointerId)return;const r=base.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),scale=d>max?max/d:1;joy={x:dx*scale/max,y:dy*scale/max};knob.style.transform=`translate(calc(-50% + ${joy.x*max}px),calc(-50% + ${joy.y*max}px))`;};base.addEventListener('pointerdown',e=>{pid=e.pointerId;base.setPointerCapture(pid);move(e);});base.addEventListener('pointermove',move);const end=e=>{if(pid!==e.pointerId)return;pid=null;joy={x:0,y:0};knob.style.transform='translate(-50%,-50%)';};base.addEventListener('pointerup',end);base.addEventListener('pointercancel',end);}
bindStick();
const look=$('#lookZone');look.addEventListener('pointerdown',e=>{lookTouch={id:e.pointerId,x:e.clientX,y:e.clientY};look.setPointerCapture(e.pointerId);});look.addEventListener('pointermove',e=>{if(!lookTouch||lookTouch.id!==e.pointerId)return;const dx=e.clientX-lookTouch.x,dy=e.clientY-lookTouch.y;player.yaw-=dx*.006;player.pitch=Math.max(-1.25,Math.min(1.25,player.pitch-dy*.005));lookTouch={id:e.pointerId,x:e.clientX,y:e.clientY};});const endLook=e=>{if(lookTouch?.id===e.pointerId)lookTouch=null;};look.addEventListener('pointerup',endLook);look.addEventListener('pointercancel',endLook);
$('#fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;fire();});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#fireBtn').addEventListener(ev,()=>fireHeld=false));$('#reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload();});$('#actionBtn').addEventListener('pointerdown',e=>{e.preventDefault();secureCore();});
// Geometry-based world collision keeps the player inside the facility and out of solid props.
const worldColliders=[];
for(const o of scene.children){if(!o.isMesh)continue;const b=new THREE.Box3().setFromObject(o);if(b.max.y>.18&&b.min.y<1.78&&b.max.x-b.min.x<20&&b.max.z-b.min.z<40)worldColliders.push({minX:b.min.x,maxX:b.max.x,minZ:b.min.z,maxZ:b.max.z});}
function blocked(x,z){const r=.32;for(const b of worldColliders){if(x+r>b.minX&&x-r<b.maxX&&z+r>b.minZ&&z-r<b.maxZ)return true;}return false;}
function reload(){if(!state.running||state.reloadTimer>0||player.ammo===player.mag||player.reserve<=0)return;state.reloadTimer=1.15;toast('RELOADING');}
function flashHit(){const el=$('#hitmarker');el.classList.add('on');setTimeout(()=>el.classList.remove('on'),110);}
const tracers=[];
function makeTracer(end){const start=new THREE.Vector3();camera.getWorldPosition(start);camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(.7).add(start);const geom=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(geom,new THREE.LineBasicMaterial({color:0xc9ff9a,transparent:true,opacity:.8}));scene.add(line);tracers.push({line,life:.055});}
