 const hits=raycaster.intersectObjects(enemies.filter(e=>e.userData.alive),true);let target=null;
 for(const h of hits){let p=h.object;while(p&& !p.userData?.alive)p=p.parent;if(p&&p.userData?.alive){target=p;break;}}
 const end=target?raycaster.ray.at(hits.find(h=>{let p=h.object;while(p&&!p.userData?.alive)p=p.parent;return p===target;})?.distance||8,new THREE.Vector3()):raycaster.ray.at(24,new THREE.Vector3());makeTracer(end);
 if(target){target.userData.hp-=50;flashHit();target.traverse(o=>{if(o.isMesh&&o.material?.emissive){o.material.emissive.setHex(0x441009);setTimeout(()=>o.material?.emissive?.setHex(0),100);}});if(target.userData.hp<=0){target.userData.alive=false;state.kills++;target.rotation.x=-1.05;target.position.y=-.25;toast('HOSTILE DOWN');}}
 $('#ammo').innerHTML=`${player.ammo} <em>/ ${player.reserve}</em>`;
}
function secureCore(){if(state.core||player.pos.distanceTo(new THREE.Vector3(8.7,0,-26.4))>2.6)return;state.core=true;scene.remove(core);scene.remove(coreLight);updateObjective();toast('INTEL SECURED / PROCEED TO EXTRACTION');}
function updateEnemies(dt,t){for(const e of enemies){if(!e.userData.alive)continue;const d=e.position.distanceTo(player.pos);e.userData.phase+=dt*2;const origin=e.userData.origin;e.position.x=origin.x+Math.sin(e.userData.phase*.4)*e.userData.patrol*.8;e.position.z=origin.z+Math.cos(e.userData.phase*.35)*e.userData.patrol*.55;e.lookAt(player.pos.x,1.1,player.pos.z);
 if(d<15){state.alert=Math.max(state.alert,3);e.userData.fire-=dt;if(d<12&&e.userData.fire<=0){e.userData.fire=1.5+Math.random()*1.5;const chance=Math.max(.2,.72-d/22);if(Math.random()<chance){player.health=Math.max(0,player.health-(5+Math.floor(Math.random()*5)));state.damageFlash=.18;$('#health').textContent=`${player.health}%`;if(player.health<=0)setEnd(false);}}}
 }}

